function makeWing(side) {
  // side: -1 left, +1 right. The wing sweeps back and outward from the shoulder.
  const pivot = new THREE.Group();
  pivot.position.set(0.82 * side, 1.86, 0.22);

  const shoulder = shadowed(new THREE.Mesh(new THREE.SphereGeometry(0.56, 20, 16), MAT.feather));
  shoulder.scale.set(0.78, 0.62, 1.12);
  shoulder.position.set(0.12 * side, 0.0, 0.02);
  pivot.add(shoulder);

  // upper arm / inner wing
  const upper = shadowed(new THREE.Mesh(new THREE.SphereGeometry(0.56, 20, 16), MAT.feather));
  upper.scale.set(1.35, 0.34, 1.15);
  upper.position.set(0.72 * side, -0.08, -0.42);
  upper.rotation.set(0, -0.42 * side, -0.14 * side);
  pivot.add(upper);

  // outer wing — long, flat, swept further back
  const fore = shadowed(new THREE.Mesh(new THREE.SphereGeometry(0.56, 20, 16), MAT.feather));
  fore.scale.set(1.55, 0.22, 1.05);
  fore.position.set(1.62 * side, -0.26, -1.28);
  fore.rotation.set(0, -0.82 * side, -0.1 * side);
  pivot.add(fore);

  // primary feathers fanning out at the wing tip
  const featherGeo = new THREE.BoxGeometry(1.15, 0.06, 0.3);
  for (let i = 0; i < 5; i++) {
    const f = shadowed(new THREE.Mesh(featherGeo, MAT.featherShade));
    const t = i / 4;
    f.position.set(side * (2.16 + t * 0.5), -0.34 - t * 0.16, -1.72 - t * 0.62);
    f.rotation.set(0, side * (-0.62 - t * 0.62), side * (-0.06 - t * 0.3));
    f.scale.set(0.86 + t * 0.42, 1, 1);
    pivot.add(f);
  }
  return pivot;
}

